cd /work/tmp && python3 -c "
import random
lines = [l for l in open('fib_mix.txt').read().split('\n') if l.strip()]
rng = random.Random(1234)
for i in range(3):
    rng.shuffle(lines)
    open('shuf%d.txt' % i, 'w').write('\n'.join(lines) + '\n')
" && for i in 0 1 2; do /work/submit/planb64 build shuf$i.txt shuf$i.idx && cmp shuf$i.idx fib_mix.idx && echo "shuffle $i identical"; done
# also with blank lines and CRLF mixed in
python3 -c "
lines = [l for l in open('fib_mix.txt').read().split('\n') if l.strip()]
import random; rng = random.Random(7); rng.shuffle(lines)
out = []
for l in lines:
    out.append(l)
    if rng.random() < 0.1: out.append('')
    if rng.random() < 0.1: out.append('   ')
    if rng.random() < 0.05: out.append('\t\r')
open('shufmess.txt','w').write('\r\n'.join(out) + '\r\n')
" && /work/submit/planb64 build shufmess.txt shufmess.idx && cmp shufmess.idx fib_mix.idx && echo "messy/CRLF/shuffled FIB -> identical image"
